"""Plots based on actual predictions generated by the reproduction pipeline."""
from pathlib import Path
import numpy as np


def save_examples(x: np.ndarray, y: np.ndarray, probabilities: np.ndarray, destination: str | Path, pad: int = 0, count: int = 3):
    import matplotlib
    matplotlib.use("Agg")
    import matplotlib.pyplot as plt
    count = min(count, len(x))
    fig, axes = plt.subplots(count, 3, figsize=(11, 3.6 * count), squeeze=False)
    for k in range(count):
        xi = x[k, pad:-pad, pad:-pad] if pad else x[k]
        yi = y[k, pad:-pad, pad:-pad, 0] if pad else y[k, :, :, 0]
        pi = probabilities[k, pad:-pad, pad:-pad, 0] if pad else probabilities[k, :, :, 0]
        # Channel order / band identities not documented by provided dataset.
        # Display bands 0,1,2 as a VISUALIZATION ONLY, not calibrated true color.
        composite = xi[..., :3]
        low = np.percentile(composite, 2, axis=(0, 1))
        high = np.percentile(composite, 98, axis=(0, 1))
        composite = np.clip((composite - low) / np.maximum(high - low, 1e-6), 0, 1)
        panels = [(composite, "Channels 0/1/2 (illustrative)"), (yi, "Ground-truth mask"), ((pi > .5), "U-Net prediction")]
        for j, (img, title) in enumerate(panels):
            axes[k, j].imshow(img, cmap=None if j == 0 else "gray", vmin=0 if j else None, vmax=1 if j else None)
            axes[k, j].set_title(f"Patch {k+1} · {title}", fontsize=10)
            axes[k, j].axis("off")
    fig.suptitle("Sentinel-2 binary segmentation — generated from model predictions", fontsize=14, fontweight="bold")
    fig.tight_layout()
    destination = Path(destination)
    destination.parent.mkdir(parents=True, exist_ok=True)
    fig.savefig(destination, dpi=170, bbox_inches="tight")
    plt.close(fig)


def save_history(history: dict, destination: str | Path):
    import matplotlib
    matplotlib.use("Agg")
    import matplotlib.pyplot as plt
    fig, axes = plt.subplots(1, 2, figsize=(12, 4))
    for ax, metric in zip(axes, ("loss", "accuracy")):
        for key in (metric, "val_"+metric):
            if key in history:
                ax.plot(range(1, len(history[key])+1), history[key], label=key.replace("val_", "validation "))
        ax.set_xlabel("Epoch")
        ax.set_ylabel(metric.title())
        ax.set_title(metric.title() + " by epoch")
        ax.legend()
        ax.grid(alpha=.2)
    fig.tight_layout()
    destination = Path(destination)
    destination.parent.mkdir(parents=True, exist_ok=True)
    fig.savefig(destination, dpi=160)
    plt.close(fig)
